 if not found then raise exception 'Falta iniciar la carga o ya se publicó. Revisa 000_iniciar.sql';end if;
 v_esperada=v_datos#>>'{metadatos,partes,reglas_0011,sha256}';
 if v_datos#>>'{metadatos,lote}' is distinct from '76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' or v_esperada is distinct from 'c655f48da211426f5390e399b3b72bdf49a09ccbb253df8a3438745d89fa9fa1'
 or encode(sha256(convert_to(v_fragmento,'UTF8')),'hex') is distinct from v_esperada then
  raise exception 'Fragmento reglas_0011 incorrecto; no se guardó';
 end if;
 update public.s911_catalogos set fuentes=jsonb_set(fuentes,'{fragmentos,reglas_0011}',to_jsonb(v_fragmento),true)
 where sha256='CARGA911:76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' and edicion='CARGA_2026-2027';
end $parte911$;
select 'PARTE_027_OK' estado,
